<?php require __DIR__.'/app/bootstrap.php';$u=require_user();$sid=(int)($_GET['service']??$_POST['service_id']??0);$msg='';$err='';
$q=db()->prepare('SELECT s.*,p.name product_name FROM services s LEFT JOIN store_products p ON p.id=s.product_id WHERE s.id=? AND s.user_id=?');$q->execute([$sid,$u['id']]);$s=$q->fetch();if(!$s){http_response_code(404);die('Service not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$pid=(int)($_POST['product_id']??0);if(!$pid)throw new RuntimeException('Choose a package.');$iid=create_upgrade_invoice($sid,$pid);header('Location:/billing.php?upgrade_invoice='.$iid);exit;}catch(Throwable $e){$err=$e->getMessage();}}
$products=db()->query('SELECT * FROM store_products WHERE active=1 ORDER BY price_monthly,sort_order,id')->fetchAll();$hist=db()->prepare('SELECT c.*,p.name new_product_name FROM service_changes c LEFT JOIN store_products p ON p.id=c.new_product_id WHERE c.service_id=? ORDER BY c.id DESC');$hist->execute([$sid]);$hist=$hist->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Upgrade <?=e($s['name'])?> | FoxNetwork</title><link rel="stylesheet" href="/assets/portal.css?v=<?=@filemtime(__DIR__.'/assets/portal.css')?>"></head><body><div class="content upgrade-page"><div class="eyebrow">SERVICE UPGRADE</div><h1><?=e($s['name'])?></h1><p class="muted">Current package: <b><?=e($s['product_name']??'Imported / unmapped')?></b> · €<?=number_format((float)$s['price_monthly'],2)?>/month</p><?php if($err):?><div class="error"><?=e($err)?></div><?php endif?><section class="upgrade-grid"><?php foreach($products as $p):?><form method="post" class="card upgrade-card"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="service_id" value="<?=e($sid)?>"><input type="hidden" name="product_id" value="<?=e($p['id'])?>"><div class="eyebrow"><?=((int)$p['id']===(int)$s['product_id'])?'CURRENT':'PACKAGE'?></div><h2><?=e($p['name'])?></h2><div class="upgrade-price">€<?=number_format((float)$p['price_monthly'],2)?><small>/month</small></div><ul><li><?=e($p['ram_mb'])?> MB RAM</li><li><?=e($p['cpu_percent'])?>% CPU</li><li><?=e($p['disk_mb'])?> MB storage</li><li><?=e($p['backups'])?> backups</li><li><?=e($p['database_limit'])?> databases</li></ul><button class="btn primary" <?=((int)$p['id']===(int)$s['product_id'])?'disabled':''?>>Choose package</button></form><?php endforeach?></section><section class="card" style="margin-top:20px"><div class="cardhead"><b>CHANGE HISTORY</b></div><?php if(!$hist):?><div class="empty muted">No package changes yet.</div><?php endif?><?php foreach($hist as $h):?><div class="order-row"><div><b><?=e($h['new_product_name']??'Package change')?></b><div class="muted small"><?=e($h['created_at'])?></div></div><span class="order-status status-<?=e($h['status'])?>"><?=e(strtoupper($h['status']))?></span></div><?php endforeach?></section><p><a class="btn" href="/client">← Back to dashboard</a></p></div></body></html>
